use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let all_frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < all_frames.len() {
        match all_frames.get(index: i) {
            Some(frame) => {
                let value = match relay.feed.decode(frame: frame) {
                    Ok(v) => v,
                    Err(_) => 0,
                };
                total = total + value;
                unit
            },
            None => unit,
        };
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = galley.menu.board();
    var i = 0;
    while i < dishes.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        match dishes.get(index: i) {
            Some(dish) => galley.kitchen.serve(io: io, dish: dish)?,
            None => unit,
        };
        i = i + 1;
    }
    return Ok(unit);
}

