use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(index: i) {
            Some(plank) if mill.rules.keeps(plank: plank) => labels.push(item: mill.rules.label(plank: plank)),
            Some(_) => unit,
            None => unit,
        };
        i = i + 1;
    }
    labels.join(sep: ",")
}

