use harbor.signal;

fn render(signal: harbor.signal.Signal) -> String {
    match signal {
        harbor.signal.Signal.Calm => "calm",
        harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
        harbor.signal.Signal.Fog(density) => "fog:".concat(other: density),
    }
}

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var rendered: List<String> = [];
    var i = 0;
    while i < signals.len() {
        match signals.get(index: i) {
            Some(signal) => rendered.push(item: render(signal)),
            None => unit,
        };
        i = i + 1;
    }
    rendered.join(sep: ";")
}
